 p=Path('papers/downloads/coverage')/file if file else None
 out.append(dict(id='coverage-'+id,title=title,authors=authors,year=year,doi=doi,source_url=source,fulltext_url=fulltext,local_path=str(p)if p and p.exists()else None,status=status or('acquired'if p and p.exists()else'metadata_only'),topics=topics,relevance=relevance,evidence=evidence or('Local fulltext identity, abstract and selected methods/discussion inspected; not independently replicated.'if p and p.exists()else'Primary metadata/abstract inspected; no acquired fulltext or validated calculations.'),acquisition_note=note,**extra))
